window.JoranTeacherVoiceReview54={"version":54,"recordings":[{"slot":"pokok:page2","text":"Tok Wan mengisi baldi dengan air. Iman membantu Hana menyiram anak pokok dengan cermat. Kemudian, mereka mengutip daun kering di sekitar pasu.","takeId":"615c47f6-0aeb-494f-9c04-b8f54d7099ca","savedAt":1792408196910,"name":"bacaan-pokok-page2.webm","url":"data:audio/webm;codecs=opus;base64,","duration54":2.58,"nonSilent54":true,"storyVersion":37},{"slot":"sihat:page4","text":"Sebelum pulang, Tok Wan melipat tikar. Hana mengajak Iman mengumpulkan sampah supaya tempat berkelah kekal bersih. Mereka membuang sampah ke dalam tong sampah.","takeId":"2d719527-cc06-492b-be09-73945aa6aa34","savedAt":1792408669806,"name":"bacaan-sihat-page4.webm","url":"data:audio/webm;codecs=opus;base64,","duration54":1.86,"nonSilent54":true,"storyVersion":37},{"slot":"sihat:page4","text":"Sebelum pulang, Tok Wan melipat tikar. Hana mengajak Iman mengumpulkan sampah supaya tempat berkelah kekal bersih. Mereka membuang sampah ke dalam tong sampah.","takeId":"38ed0836-cf00-4ecb-9165-466296341448","savedAt":1792408646760,"name":"bacaan-sihat-page4.webm","url":"data:audio/webm;codecs=opus;base64,","duration54":3.24,"nonSilent54":false,"storyVersion":37}]};
